 {tab==='layers'&&<>{section(t('YOUR EXPOSURES','نوردهی‌های شما'))}{layers.map((a,i)=><TouchableOpacity key={a.uri||i} onPress={()=>setSelectedLayer(i)} activeOpacity={0.8} style={[s.layer,selectedLayer===i&&{borderWidth:1,borderColor:C.gold}]}><Image source={{uri:a.uri}} style={s.thumb}/><View style={{flex:1}}><Text style={s.layerName}>{t('Exposure','نوردهی')} {i+1}</Text><Text style={s.small}>{a.width} × {a.height}</Text></View><TouchableOpacity onPress={()=>moveLayer(i,-1)} disabled={i===0}><Text style={{color:i===0?C.line:C.text,fontSize:18}}>↑</Text></TouchableOpacity><TouchableOpacity onPress={()=>moveLayer(i,1)} disabled={i===layers.length-1}><Text style={{color:i===layers.length-1?C.line:C.text,fontSize:18}}>↓</Text></TouchableOpacity><TouchableOpacity onPress={()=>removeLayer(i)}><Text style={{color:C.red}}>✕</Text></TouchableOpacity></TouchableOpacity>)}{layers.length>0&&<><Text style={s.helper}>{t('Selected layer','لایه انتخاب‌شده')} {selectedLayer+1}</Text><View style={s.wrap}>{pill(t('Choose layer mask','انتخاب ماسک لایه'),false,()=>{setMaskTarget('layer');setShowMasks(true)})}{pill(t('Apply mask','اعمال ماسک'),!!layerMasks[selectedLayer],()=>setLayerMasks(old=>{const a=[...old];a[selectedLayer]=mask.path;return a}))}{pill(t('Clear mask','حذف ماسک'),false,()=>setLayerMasks(old=>{const a=[...old];a[selectedLayer]=null;return a}))}</View><View style={s.wrap}>{pill('−',false,()=>adjustTransform('scale',-.1))}{pill('＋',false,()=>adjustTransform('scale',.1))}{pill('↶',false,()=>adjustTransform('rotation',-5))}{pill('↷',false,()=>adjustTransform('rotation',5))}{pill('Reset transform',false,()=>setTransforms(old=>{const a=[...old];a[selectedLayer]={scale:1,rotation:0,x:0,y:0};return a}))}</View></>}<TouchableOpacity style={s.secondaryWide} onPress={chooseGallery}><Text style={s.secondaryText}>{t('Add more exposures','افزودن نوردهی بیشتر')}</Text></TouchableOpacity></>}
