class DouExpoErrorBoundary extends React.Component<any,{failed:boolean}>{state={failed:false};static getDerivedStateFromError(){return {failed:true}}componentDidCatch(error:any,info:any){try{FileSystem.writeAsStringAsync((FileSystem.documentDirectory||'')+'dou-expo-last-error.txt',String(error?.stack||error)+'\\n'+String(info?.componentStack||''),{encoding:FileSystem.EncodingType.UTF8})}catch(e){} }render(){if(this.state.failed)return <SafeAreaView style={{flex:1,backgroundColor:C.bg,justifyContent:'center',padding:24}}><Text style={{color:C.text,fontSize:20,fontWeight:'800',textAlign:'center',marginBottom:12}}>Dou Expo متوقف شد</Text><Text style={{color:C.muted,fontSize:14,textAlign:'center',lineHeight:24}}>برای جلوگیری از فشار بیشتر، برنامه را ببندید و دوباره باز کنید. آخرین وضعیت ذخیره‌شده در صورت امکان بازیابی می‌شود.</Text><TouchableOpacity onPress={()=>this.setState({failed:false})} style={{marginTop:24,backgroundColor:C.gold,padding:16,borderRadius:12}}><Text style={{color:C.bg,textAlign:'center',fontWeight:'800'}}>تلاش دوباره</Text></TouchableOpacity></SafeAreaView>;return this.props.children}}
export default function App(){return <DouExpoErrorBoundary><AppContent/></DouExpoErrorBoundary>}
